import os, csv, json

CSV_PATH = "storage/shared/agency_lab/analyses/csv/joint_metrics_v2_5_per_lineage_rolling.csv"
OUT_DIR = "storage/shared/agency_lab/analyses/figures"
os.makedirs(OUT_DIR, exist_ok=True)
PNG_PATH = os.path.join(OUT_DIR, "quickstart_v2_5_rolling_persistence.png")

def read_rows(path):
    with open(path, "r", encoding="utf-8") as f:
        return list(csv.DictReader(f))

def to_float(s, default=0.0):
    try:
        return float(s)
    except Exception:
        return default

def main():
    rows = read_rows(CSV_PATH)
    # Build series per lineage: (start, persistence_rate)
    series = {}
    for r in rows:
        lin = r.get("lineage", "").strip().lower()
        if not lin:
            continue
        start = int(r.get("start", 0))
        pr = to_float(r.get("persistence_rate", 0.0))
        series.setdefault(lin, []).append((start, pr))

    # Sort by start
    for lin in series:
        series[lin].sort(key=lambda x: x[0])

    # Try to plot
    try:
        import matplotlib.pyplot as plt  # type: ignore
        plt.figure(figsize=(8, 4.5))
        for lin, pts in sorted(series.items()):
            xs = [p[0] for p in pts]
            ys = [p[1] for p in pts]
            plt.plot(xs, ys, marker="o", linewidth=1.5, label=lin)
        plt.xlabel("window start tick (W=5, step=2)")
        plt.ylabel("persistence_rate")
        plt.title("v2.5 rolling persistence by lineage")
        plt.legend(loc="best", fontsize=8)
        plt.tight_layout()
        plt.savefig(PNG_PATH, dpi=150)
        print("PLOT_SAVED", PNG_PATH)
    except Exception as e:
        print("MATPLOTLIB_UNAVAILABLE_OR_ERROR", str(e))
        # Fallback: print 3-line summary per lineage
        summary = {lin: pts[:3] for lin, pts in series.items()}
        print("SERIES_SAMPLE_JSON")
        print(json.dumps(summary, indent=2))

    return 0

if __name__ == "__main__":
    import sys
    try:
        sys.exit(main())
    except Exception as e:
        print("ERROR", str(e))
        sys.exit(1)
